func CreateChange(
	ctx context.Context,
	exec storage.Executor,
	actorID *uuid.UUID,
	correlationID uuid.UUID,
	environmentID uuid.UUID,
	correctsChangeID *uuid.UUID,
	opts ...ChangeOption,
) (models.ChangeEntity, error) {
	built := BuildChange(actorID, correlationID, environmentID, correctsChangeID, opts...)

	entity := models.ChangeEntity{
		ID:                uuid.New(),
		CreatedAt:         time.Now(),
		UpdatedAt:         time.Now(),
		Sequence:          built.Sequence,
		Kind:              built.Kind,
		TriggerType:       built.TriggerType,
		ActorType:         built.ActorType,
		ActorID:           built.ActorID,
		CauseSystem:       built.CauseSystem,
		CauseReference:    built.CauseReference,
		CorrelationID:     built.CorrelationID,
		CorrectionContext: built.CorrectionContext,
		Summary:           built.Summary,
		Status:            built.Status,
		RequestedAt:       built.RequestedAt,
		CommittedAt:       built.CommittedAt,
		StartedAt:         built.StartedAt,
		FinishedAt:        built.FinishedAt,
		CancelledAt:       built.CancelledAt,
		Error:             built.Error,
		EnvironmentID:     built.EnvironmentID,
		CorrectsChangeID:  built.CorrectsChangeID,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.ChangeEntity{}, err
	}

	return entity, nil
}

func CreateChanges(
	ctx context.Context,
	exec storage.Executor,
	actorID *uuid.UUID,
	correlationID uuid.UUID,
	environmentID uuid.UUID,
	correctsChangeID *uuid.UUID,
	count int,
	opts ...ChangeOption,
) ([]models.ChangeEntity, error) {
	changes := make([]models.ChangeEntity, 0, count)

	for i := range count {
		entity, err := CreateChange(
			ctx,
			exec,
			actorID,
			correlationID,
			environmentID,
			correctsChangeID,
			opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create change %d: %w", i+1, err)
		}
		changes = append(changes, entity)
	}

	return changes, nil
}

